/// Constructor for a 256-bit SFC64-style state from an optional seed.
///
/// Guarantees:
/// - `None` => all components are zero.
/// - `Some(seed)` => state is not all-zero; first component is `seed` unless
///   `seed == 0`, in which case it is set to `1`. Remaining components are zero.
pub fn sfc64(seed: Option<u64>) -> SFC64State {
    match seed {
        None => SFC64State { a: 0, b: 0, c: 0, d: 0 },
        Some(x) => SFC64State {
            a: if x == 0 { 1 } else { x },
            b: 0,
            c: 0,
            d: 0,
        },
    }
}

